import Image from 'next/image';

export function ProductCard({ product }: { product: Product }) {
  return (
    <a href={`/p/${product.id}`} className="card">
      <div className="thumb">
        <Image
          src={product.imageUrl}
          alt={product.name}
          fill
          sizes="100vw"
          priority
        />
      </div>
      <span>{product.name}</span>
    </a>
  );
}

